  "supplier_set": {
    "name": "$$\\{A,B,C\\}$$",
    "size": "$$3$$",
    "elements": [
      {
        "id": "$$A$$",
        "cost_per_order": "$$120$$",
        "tables_per_order": "$$20$$"
      },
      {
        "id": "$$B$$",
        "cost_per_order": "$$110$$",
        "tables_per_order": "$$15$$"
      },
      {
        "id": "$$C$$",
        "cost_per_order": "$$100$$",
        "tables_per_order": "$$15$$"
      }
    ]
  },
  "planning_horizon": {
    "period_set": "$$\\{1\\}$$",
    "size": "$$1$$",
    "description": "Single ordering period"
  },
  "demand_limits": {
    "minimum_total_tables": "$$150$$",
    "maximum_total_tables": "$$600$$"
  },
  "logical_rules": [
    {
      "type": "quantity_dependency",
      "trigger_supplier": "$$A$$",
      "required_supplier": "$$B$$",
      "minimum_quantity_if_trigger_used": "$$30$$"
    },
    {
      "type": "usage_dependency",
      "trigger_supplier": "$$B$$",
      "required_supplier": "$$C$$"
    }
  ],
  "variable_domains": {
    "order_counts": "Nonnegative integer-valued for each supplier",
    "supplier_usage": "Binary for each supplier"
  }
